//! Stage timings for native sparse computation; no Polars plugin dispatch.
//! Input is column-major little-endian f64, generated by benchmarks/profile_sparse.py.
use std::{env, error::Error, fs, time::Instant};

use cocycle::diagram::IntervalEnd;
use cocycle::filtration::ApproximateRipsBuilder;
use cocycle::geometry::{MetricPolicy, PointCloudView};
use cocycle::persistence::PersistenceExt;

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<_> = env::args().collect();
    if args.len() != 7 {
        return Err("expected INPUT N D EPSILON implicit|expanded OUTPUT".into());
    }
    let n: usize = args[2].parse()?;
    let d: usize = args[3].parse()?;
    let epsilon: f64 = args[4].parse()?;
    let count = n.checked_mul(d).ok_or("coordinate count overflow")?;
    let bytes = fs::read(&args[1])?;
    if bytes.len() != count.checked_mul(8).ok_or("byte count overflow")? {
        return Err("input shape mismatch".into());
    }
    let columns: Vec<f64> = bytes
        .chunks_exact(8)
        .map(|b| f64::from_le_bytes(b.try_into().expect("eight bytes")))
        .collect();
    let started = Instant::now();
    let mut packed = Vec::with_capacity(count);
    for row in 0..n {
        for column in 0..d {
            packed.push(columns[column * n + row]);
        }
    }
    let points = PointCloudView::new(&packed, n, d)?;
    let packing = started.elapsed().as_secs_f64();
    let started = Instant::now();
    let prepared =
        ApproximateRipsBuilder::from_points(points, epsilon, MetricPolicy::Unchecked).prepare()?;
    let preparation = started.elapsed().as_secs_f64();
    let edges = prepared.graph().edges().len();
    let (expansion, simplices, compute, result) = match args[5].as_str() {
        "implicit" => {
            let started = Instant::now();
            let result = prepared.persistence().max_homology_dimension(1).compute()?;
            (0.0, 0, started.elapsed().as_secs_f64(), result)
        }
        "expanded" => {
            let started = Instant::now();
            let expanded = prepared.expand(2)?;
            let expansion = started.elapsed().as_secs_f64();
            let simplices = expanded.complex().len();
            let started = Instant::now();
            let result = expanded.persistence().max_homology_dimension(1).compute()?;
            (
                expansion,
                simplices,
                started.elapsed().as_secs_f64(),
                result,
            )
        }
        _ => return Err("unknown mode".into()),
    };
    let mut intervals = String::new();
    for i in result.diagram().intervals() {
        let end = match i.end() {
            IntervalEnd::Finite(v) => format!("finite:{:016x}", v.to_bits()),
            IntervalEnd::Essential => "essential".to_owned(),
            IntervalEnd::RightCensored { through } => {
                format!("censored:{:016x}", through.to_bits())
            }
        };
        intervals.push_str(&format!(
            "{}\t{:016x}\t{}\n",
            i.dimension(),
            i.birth().to_bits(),
            end
        ));
    }
    fs::write(&args[6], intervals)?;
    let status = fs::read_to_string("/proc/self/status")?;
    let peak_rss_kib: u64 = status
        .lines()
        .find_map(|line| line.strip_prefix("VmHWM:"))
        .ok_or("missing Linux VmHWM")?
        .split_whitespace()
        .next()
        .ok_or("empty VmHWM")?
        .parse()?;
    let peak_rss_mib = peak_rss_kib as f64 / 1024.0;
    println!(
        "{{\"peak_rss_mib\":{peak_rss_mib},\"packing_seconds\":{packing},\"preparation_seconds\":{preparation},\"expansion_seconds\":{expansion},\"compute_seconds\":{compute},\"edges\":{edges},\"simplices\":{simplices}}}"
    );
    Ok(())
}
